select jsonb_build_object('functions',(select jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'owner',pg_get_userbyid(p.proowner),'definer',p.prosecdef,'volatility',p.provolatile,'config',p.proconfig,'executors',(select jsonb_agg(case when a.grantee=0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end order by a.grantee) from aclexplode(p.proacl) a))) from pg_proc p where p.oid in (to_regprocedure('public.math_learning(jsonb)'),to_regprocedure('math_private.learning_state(uuid)'),to_regprocedure('math_private.learning_eligibility(uuid,timestamptz)'),to_regprocedure('math_private.validate_output(uuid,jsonb)'))),'tables',(select jsonb_agg(jsonb_build_object('name',relname,'owner',pg_get_userbyid(relowner),'rls',relrowsecurity,'acl',relacl::text)) from pg_class where oid in ('public.math_solution_exposures'::regclass,'public.math_hint_exposures'::regclass)),'constraints',(select jsonb_agg(conname) from pg_constraint where conname in ('math_evaluation_output_identity','math_solution_exposure_one_binding','math_solution_generated_output_fk')),'indexes',(select jsonb_agg(indexname) from pg_indexes where indexname in ('math_hint_delivery_history','math_solution_delivery_history')),'memberships',(select jsonb_agg(jsonb_build_array(pg_get_userbyid(roleid),pg_get_userbyid(member),pg_get_userbyid(grantor),admin_option,inherit_option,set_option) order by roleid,member) from pg_auth_members where roleid in ('math_executor'::regrole,'math_extraction_worker'::regrole,'math_evaluation_worker'::regrole)),'temporary_create',has_schema_privilege('math_executor','math_private','CREATE')) postflight;
